	public static float GetRange(int reach)
	{
		return reach switch
		{
			0 => 120f, 
			1 => 180f, 
			2 => 250f, 
			3 => 350f, 
			4 => 500f, 
			5 => 900f, 
			_ => 100f, 
		};
	}
